  const failures = [];
  for (const interaction of interactions) {
    const actual = getActualResponse(interaction.request);
    // TODO: push interaction.description onto failures when actual doesn't
    // match interaction.response (status or JSON.stringify(body))
  }
  return { passed: failures.length === 0, failures };
}

items.solution:
function verifyContract(interactions, getActualResponse) {
  const failures = [];
  for (const interaction of interactions) {
    const actual = getActualResponse(interaction.request);
    if (actual.status !== interaction.response.status) {
      failures.push(interaction.description);
      continue;
    }
    if (JSON.stringify(actual.body) !== JSON.stringify(interaction.response.body)) {
      failures.push(interaction.description);
    }
  }
  return { passed: failures.length === 0, failures };
}

