function buildContract(consumer, provider, calls) {
  // TODO: return { consumer, provider, interactions } where interactions
  // is calls mapped so a missing description becomes
  // `a request for ${call.request.path}`, and an existing one is kept
}

items.solution:
function buildContract(consumer, provider, calls) {
  return {
    consumer,
    provider,
    interactions: calls.map((call) => ({
      ...call,
      description: call.description || `a request for ${call.request.path}`,
    })),
  };
}

